#include "../../src/residual.hpp"
int main(){init_curve();auto G=load_chart();for(auto [h,w,l]:std::vector<std::tuple<F,F,F>>{{1,2,1},{31,2,73},{73,25,31}}){auto r=specialize_scale(residual_all_scales(evaluate(G,h,w)),l);auto dr=derivative(r);auto d=gcd(r,dr);std::cout<<h<<","<<w<<","<<l<<" degree="<<r.deg()<<" d_degree="<<dr.deg()<<" gcd_degree="<<d.deg()<<"\n";for(F x:{0u,1u,2u,3u,25u})std::cout<<"x="<<x<<" value="<<eval(r,x)<<" derivative="<<eval(dr,x)<<"\n";std::vector<Poly>c(5);auto r3=power(r,3);for(int a=0;a<5;a++){for(int b=a;b<=r3.deg();b+=5)c[a].push_back(r3[b]);c[a].trim();}auto g=c[0];for(int a=1;a<5;a++)g=gcd(g,c[a]);std::cout<<"A3 residues gcd_degree="<<g.deg()<<"\n";}}
